<template>
	<view class="tab-bar">
		<button v-for="tab in tabs" :key="tab.key" class="tab-item" :class="{ active: activeView === tab.key }" @tap="$emit('switch', tab.key)"><uni-icons :type="activeView === tab.key ? tab.activeIcon : tab.icon" size="23" :color="activeView === tab.key ? '#16834d' : '#8e9690'" /><text>{{ tab.label }}</text></button>
	</view>
</template>

<script>
	export default {
		name: 'SubscriptionTabBar',
		emits: ['switch'],
		props: {
			tabs: { type: Array, default: () => [] },
			activeView: { type: String, default: 'home' }
		}
	}
</script>

